        require(wrongAmount != 1 ether);
        require(rightAmount == 1 ether);
        require(address(this).balance >= rightAmount);
        uint balBefore = address(c).balance;
        bool reverted;
        // Attempt to lock in a guess with a wrong value: must revert.
        try c.lockInGuess{value: wrongAmount}(bytes32(uint(12345))) { reverted = false; } catch { reverted = true; }
        uint balAfterWrong = address(c).balance;
        // Since the wrong-valued call reverted, the sender still has no guess locked,
        // so a correctly-valued lockInGuess must succeed.
        bool secondReverted;
        try c.lockInGuess{value: rightAmount}(bytes32(uint(67890))) { secondReverted = false; } catch { secondReverted = true; }
        assert(reverted && balAfterWrong == balBefore && !secondReverted && address(c).balance == balBefore + 1 ether);
    }
    receive() external payable {}
}

